/**
 * TableMind 真实桌游数据层（自动生成，请勿手改；重新生成运行 .workbuddy/tmp/gen_library_v2.py）
 *
 * 数据来源：BoardGameGeek 官方数据接口 api.geekdo.com
 *   第一批采集于 2026-10-05T22:37:47+0800，第二批采集于 2026-10-06T17:16:22+0800
 *   每款游戏主页：https://boardgamegeek.com/boardgame/<bgg_id>
 *   规格字段（人数 / 时长 / 年龄 / 发行年份 / 设计师 / 出版社 / 插画师 / 分类 /
 *     机制 / 获奖记录）均为接口原值，未做任何推测或补全。
 *
 * 图片分为两类，用途严格区分：
 *   - official_images：官方宣传图（盒装封面等），用于详情页头图区；
 *   - player_images ：玩家真实游玩照片（BGG 用户上传，保留 caption 与上传者），
 *                     只出现在“游戏图集”。
 *   两者均不使用任何视频封面。教学视频缩略图单独存放在 /videos/<slug>/ 下。
 *
 * 评分：avg_rating / rating_count / complexity 不在此数据层内写死，
 *   改由后端按本系统玩家的真实评测聚合后返回（见 /api/rankings）。
 */

export interface GameSource {
  label: string;
  url: string;
}

export interface TeachingVideo {
  bvid: string;
  title: string;
  author: string;
  /** 秒 */
  durationSeconds: number;
  views: number;
  /** 视频缩略图（B站），与桌游图片分离存放 */
  cover: string;
  url: string;
}

export interface GameImage {
  src: string;
  /** 图片说明 */
  caption: string;
  /** 上传者（BGG 用户名） */
  uploader?: string;
  /** BGG 图片页，用于核对来源 */
  sourceUrl?: string;
}

export interface GameDetail {
  id: number;
  /** BGG 站内 ID；非 BGG 来源（如集石补录）的桌游为 null——没有编号就不填 */
  bgg_id: number | null;
  slug: string;
  name: string;
  name_en: string | null;
  /** 中文简介，依据官方简介整理 */
  description: string;
  /** 官方英文简介原文 */
  description_official: string | null;
  min_players: number | null;
  max_players: number | null;
  play_time_text: string | null;
  play_time_minutes: number | null;
  play_time_max_minutes: number | null;
  min_age: number | null;
  /** 本系统玩家评分均值（1-10），由后端聚合；未加载时为 null */
  avg_rating: number | null;
  /** 本系统参与评分的人数；未加载时为 null */
  rating_count: number | null;
  complexity: number | null;
  categories: string[];
  categories_en: string[];
  mechanics: string[];
  mechanics_en: string[];
  designers: string[];
  artists: string[];
  publishers: string[];
  publisher: string | null;
  year_published: number | null;
  /** BGG 官方获奖 / 提名记录，原样保留英文标题 */
  honors: string[];
  cover_image: string;
  /** 官方宣传图（盒装封面等）——详情页头图区专用 */
  official_images: GameImage[];
  /** 玩家真实游玩照片——只在“游戏图集”中出现 */
  player_images: GameImage[];
  /** player_images 的别名，兼容旧调用 */
  images: GameImage[];
  videos: TeachingVideo[];
  sources: GameSource[];
}


