    description: "波多黎各位于加勒比海大安德列斯群岛，全称波多黎各自由邦，原为印第安人居住地。自从哥伦布在第二次远航中到达波多黎各后，该地就成为了西方世界的殖民地。在波多黎各的游戏中，玩家将回到航海时代，扮演那些远渡重洋的西班牙征服者，在群岛中尝试建立起繁荣富饶的殖民地，并通过完善的经营管理将物资运回祖国，以此得到国王的信任以及无上的荣耀。 波多黎各游戏中，玩家回到了航海时代，扮演那些远渡重洋的西班牙移民， 在群岛中尝试建立起繁荣的殖民地。每一位玩家都是波多黎各的种植园主，可以种植最多5种作物。玩家必须设法比竞争对手更有效的使用他们的业务：种植作物，并有效保存，在圣胡安建造有用的建筑，部署最佳效果的开拓者，在正确的时间销售作物，和最重要的——将货物装船运回欧洲获得最大利益。 游戏系统允许每位玩家在回合中选择包括拓荒者、建筑师、市长、商人、船长、工匠、淘金者在内的角色来改变每回合各阶段的执行顺序。在同一回合中没有角色能被选择两次。在整个游戏中，能够选择对自己最有利角色的玩家会赢得游戏。",
