export const hotnessCollectedAt = "2026-10-05T22:37:47+0800";
export const libraryCollectedAt = "2026-10-06T17:16:22+0800";

const bySlug = new Map<string, GameDetail>();
const byId = new Map<number, GameDetail>();
for (const g of gameLibrary) {
  bySlug.set(g.slug, g);
  bySlug.set(String(g.bgg_id), g);
  byId.set(g.id, g);
}

export function getGameByIdOrSlug(idOrSlug: string | number): GameDetail | undefined {
  const key = String(idOrSlug);
  return bySlug.get(key) ?? byId.get(Number(key));
}

export const allCategories: string[] = Array.from(
  new Set(gameLibrary.flatMap((g) => g.categories))
).sort();

export const allMechanics: string[] = Array.from(
  new Set(gameLibrary.flatMap((g) => g.mechanics))
).sort();

/**
 * 同类桌游推荐：机制重合 ×3 + 分类重合 ×2 + 人数区间重叠 + 时长接近度打分。
 */
export interface SimilarGame {
  game: GameDetail;
  score: number;
  reasons: string[];
}

export function getSimilarGames(target: GameDetail, limit = 3): SimilarGame[] {
  const scored: SimilarGame[] = [];
  for (const g of gameLibrary) {
    if (g.id === target.id) continue;
    let score = 0;
    const reasons: string[] = [];
    const sharedMec = g.mechanics.filter((m) => target.mechanics.includes(m));
    if (sharedMec.length) {
      score += sharedMec.length * 3;
      reasons.push(`共有机制：${sharedMec.slice(0, 2).join('、')}`);
    }
    const sharedCat = g.categories.filter((c) => target.categories.includes(c));
    if (sharedCat.length) {
      score += sharedCat.length * 2;
      reasons.push(`同属分类：${sharedCat.slice(0, 2).join('、')}`);
    }
    if (g.min_players != null && g.max_players != null
        && target.min_players != null && target.max_players != null) {
      const overlap = Math.min(g.max_players, target.max_players) - Math.max(g.min_players, target.min_players);
      if (overlap >= 0) {
        score += 1;
        reasons.push(`人数区间重叠（${g.min_players}-${g.max_players} 人）`);
      }
    }
    if (g.play_time_minutes != null && target.play_time_minutes != null) {
    const diff = Math.abs(g.play_time_minutes - target.play_time_minutes);
    if (diff <= 20) {
      score += 2;
      reasons.push(`时长接近（${g.play_time_text}）`);
    }
    }
    if (score > 0) scored.push({ game: g, score, reasons });
  }
  return scored.sort((a, b) => b.score - a.score).slice(0, limit);
}

export interface AwardRanking {
  game: GameDetail;
  winCount: number;
  latest: string;
}

/** 获奖榜：解析 BGG 官方获奖记录中的 Winner 条目并按获奖数排序 */
export function getAwardRankings(): AwardRanking[] {
  const out: AwardRanking[] = [];
  for (const g of gameLibrary) {
    const wins = g.honors.filter((h) => /\bWinner\b/.test(h));
    if (!wins.length) continue;
    const years = wins
      .map((h) => { const m = h.match(/(19|20)\d{2}/); return m ? Number(m[0]) : 0; })
      .filter(Boolean);
    const latestYear = years.length ? Math.max(...years) : 0;
    const latest = latestYear
      ? (wins.find((h) => h.includes(String(latestYear))) ?? wins[0])
      : wins[0];
    out.push({ game: g, winCount: wins.length, latest });
  }
  return out.sort((a, b) => b.winCount - a.winCount);
}

/** 人数文案；数据缺失时如实写「暂无」，绝不编一个数字出来 */
export function formatPlayers(g: {
  min_players: number | null;
  max_players: number | null;
}): string {
  const { min_players: lo, max_players: hi } = g;
  if (lo == null || hi == null) return '人数暂无';
  return lo === hi ? `${lo} 人` : `${lo}-${hi} 人`;
}

/** 时长文案；优先用原文描述（如「60-120 分钟」「人均 35 分钟/人」） */
export function formatPlayTime(g: {
  play_time_text: string | null;
  play_time_minutes: number | null;
}): string {
  if (g.play_time_text) return g.play_time_text;
  if (g.play_time_minutes != null) return `${g.play_time_minutes} 分钟`;
  return '时长暂无';
}

/** 年龄文案 */
export function formatAge(g: { min_age: number | null }): string {
  return g.min_age != null ? `${g.min_age}+ 岁` : '年龄暂无';
}

export function formatDuration(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${String(s).padStart(2, '0')}`;
}

export function formatViews(views: number): string {
  if (views >= 10000) return `${(views / 10000).toFixed(1)} 万`;
  return String(views);
}
